/* Simulation environment registry (Wave 3, addendum §b.8/§e.5):
 * every entry carries the registry shape the environment picker
 * consumes — {id, name, format, source, engine_targets, license} —
 * so a future environment (including a RealmForge-XR world) drops
 * in as data, not surgery. Presets are generated by the Python
 * twin (`generate_world` in src/robotforge/twin.py) for the wheeled
 * twins; no legged simulation exists, and no entry here pretends
 * otherwise. */

export interface EnvironmentEntry {
  id: string;
  name: string;
  format: "sdf" | "usd" | "gltf";
  source: string;
  engine_targets: ("gazebo" | "isaac")[];
  license: string;
  status: string;
  recorded: boolean;
}

